typedef unsigned int u_int;
typedef unsigned long long big_int;

class stringx;

class string_buf
{
protected:
	friend class stringx;
	friend inline bool operator==(const stringx& lhs, const stringx& rhs);

	big_int *data;
	int ref_count;
	int char_length;
	int block_length;
	int max_blocks;

public:
	inline bool is_equal(const string_buf &buf) const
	{
		if (buf.block_length != block_length) return false;
		for (int i = 0; i < block_length; i++) {
			if (!(buf.data[i] == data[i])) return false;
		}
		return true;
	}
};

class stringx
{
	friend inline bool operator==(const stringx& lhs, const stringx& rhs);

protected:
	char *chars;
	string_buf *my_buf;

public:
	stringx &operator=(const stringx &cp);

	inline const char *c_str() const
	{
		return chars;
	}
};

inline bool operator==(const stringx& lhs, const stringx& rhs)
{
	return lhs.my_buf->is_equal(*rhs.my_buf);
}

enum WavePerturbTypeEnum {
	WAVE_PerturbTypeRush,
	WAVE_PerturbTypeBigRush,
	WAVE_PerturbTypeSurge,
	WAVE_PerturbTypeBigSurge,
	WAVE_PerturbTypeTongue,
	WAVE_PerturbTypeBigTongue,
	WAVE_PerturbTypeMax
};

struct WaveBreakStruct {
	WavePerturbTypeEnum type;
	float time;
	float prob[WAVE_PerturbTypeMax];
};

#define WAVE_MAXBREAK 8
struct WaveBreakTypeStruct {
	stringx name;
	int numbreak;
	WaveBreakStruct breaklist[WAVE_MAXBREAK];
};

#define WAVE_MAXBREAKTYPE 8
static WaveBreakTypeStruct WAVE_BreakArray[WAVE_MAXBREAKTYPE];
static u_int WAVE_BreakTypeMax;

#define wavewarn(a)

u_int WAVE_CheckBreakType(const stringx &breakstr)
{
	u_int break_type = WAVE_MAXBREAKTYPE;

	// Find the right break type.
	for (u_int i = 0; i < WAVE_BreakTypeMax; ++i)
	{
		if (breakstr == WAVE_BreakArray[i].name)
		{
			break_type = i;
			break;
		}
	}
	if (break_type == WAVE_MAXBREAKTYPE)
	{
		if (WAVE_BreakTypeMax < WAVE_MAXBREAKTYPE)
		{
			break_type = WAVE_BreakTypeMax;
			WAVE_BreakArray[WAVE_BreakTypeMax].name = breakstr;
			++WAVE_BreakTypeMax;
		}
		else
		{
			break_type = 0;
			wavewarn(("WAVE:\tToo many break types in .beach file."));
			wavewarn(("WAVE:\tAt most %d different .break files are allowed."));
			wavewarn(("WAVE:\tReplacing break type %s by break type %s for purposes of wave effects.",
				breakstr.c_str(), WAVE_BreakArray[0].name.c_str()));
		}
	}

	return break_type;
}
